import torch.nn as nn
import torch

# Value estimator network
class QNetwork(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(4, 64), nn.ReLU(), nn.Linear(64, 2))
    def forward(self, state):
        return self.net(state)

model = QNetwork()
s = torch.rand((1, 4))
q_values = model(s)
